const IC_wave=(x,y,len,col,w=4)=>{let d=`M${x},${y}`;for(let i=1;i<=4;i++){const yy=y-i*len/4,xx=x+(i%2?10:-10);d+=` Q${xx},${y-(i-.5)*len/4} ${x},${yy}`}return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
/* a sideways wavy line from x,y going left (dir -1) or right (dir 1) */
const IC_waveH=(x,y,len,col,dir=1,w=4)=>{let d=`M${x},${y}`;for(let i=1;i<=4;i++){const xx=x+dir*i*len/4,yy=y+(i%2?10:-10);d+=` Q${x+dir*(i-.5)*len/4},${yy} ${xx},${y}`}return `<path d="${d}" fill="none" stroke="${col}" stroke-width="${w}" stroke-linecap="round"/>`};
