const IC_thermo=(x,y,col,lvl=.6,h=70)=>`<rect x="${x-8}" y="${y-h}" width="16" height="${h}" rx="8" fill="#FFFFFF" stroke="${IC_STEEL}" stroke-width="2.5"/><rect x="${x-4}" y="${y-h*lvl}" width="8" height="${h*lvl}" fill="${col}"/><circle cx="${x}" cy="${y+6}" r="13" fill="${col}" stroke="${IC_STEEL}" stroke-width="2.5"/>`;
