const IC_drop=(x,y,s,col)=>`<path d="M${x},${y-s} C${x+s*.7},${y-s*.1} ${x+s*.7},${y+s*.7} ${x},${y+s*.7} C${x-s*.7},${y+s*.7} ${x-s*.7},${y-s*.1} ${x},${y-s} Z" fill="${col}"/>`;
