function EXTRA(R,ICON){
 /* hook: fuel power in, and the engine where only part reaches the shaft */
 ICON.icFuelIn=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${IC_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}
  <rect x="26" y="40" width="80" height="100" rx="10" fill="${ORG}"/><rect x="60" y="24" width="30" height="20" rx="4" fill="${IC_STEEL}"/>${IC_drop(66,92,26,'#FFFFFF')}
  ${IC_arrow(120,90,190,90,ORG,6)}${IC_T(206,70,'fuel power in',{fs:24,fw:800,fill:ORG})}${IC_T(206,112,'35.0 kW',{fs:30,fw:800})}</g>`;
 ICON.icHeatOut=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${IC_box(0,0,380,160,{fill:'#FFFFFF',st:BLU,sw:3,r:18})}
  ${IC_block(20,40,120,100)}${IC_wave(40,36,30,TRED,3)}${IC_wave(80,36,30,TRED,3)}${IC_wave(120,36,30,TRED,3)}
  ${IC_L(140,110,186,110,IC_STEEL,10)}${IC_T(200,56,'shaft: 10.5 kW',{fs:22,fw:800,fill:BLU})}${IC_T(200,98,'the rest: heat,',{fs:22,fill:IC_GREY})}${IC_T(200,136,'but where?',{fs:24,fw:800,fill:TRED})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.icBar=(x,y)=>`<g transform="translate(${x-210} ${y-165})">${IC_T(210,30,'Pf = 35.0 kW = 100 %',{fs:26,fw:800,a:'middle',fill:BLU})}
  ${IC_L(10,56,10,46,BLU,3)}${IC_L(10,46,410,46,BLU,3)}${IC_L(410,46,410,56,BLU,3)}
  ${IC_sbar(10,66,4,160,[[30.0,'30.0',IC_GREY],[28.7,'28.7',IC_WATER],[31.0,'31.0','#868E96'],[10.3,'',TRED]],{fs:24})}
  ${IC_T(70,258,'brake',{fs:22,a:'middle',fill:IC_GREY})}${IC_T(182,258,'water',{fs:22,a:'middle',fill:IC_GREY})}${IC_T(302,258,'exhaust',{fs:22,a:'middle',fill:IC_GREY})}
  ${IC_arrow(390,300,390,232,TRED,3)}${IC_T(370,318,'rest, by difference',{fs:22,fw:800,a:'end',fill:TRED})}</g>`;
 ICON.icPhi=(x,y)=>{const x0=20,x1=400,ya=120,e0=IC_phiX(.85,x0,x1),e1=IC_phiX(.95,x0,x1),pw=IC_phiX(1.1,x0,x1),kx=110,ky=262,kr=52,pa=75*Math.PI/180;return `<g transform="translate(${x-210} ${y-165})">${IC_phiAxis(x0,x1,ya,{sides:false})}
  <rect x="${e0}" y="${ya-66}" width="${e1-e0}" height="42" rx="6" fill="${GRN}" fill-opacity=".8"/>${IC_T((e0+e1)/2,ya-78,'efficiency',{fs:22,fw:800,a:'middle',fill:GRN})}
  <circle cx="${pw}" cy="${ya-45}" r="17" fill="${ORG}"/>${IC_T(pw,ya-78,'power',{fs:22,fw:800,a:'middle',fill:ORG})}
  <circle cx="${kx}" cy="${ky}" r="${kr}" fill="none" stroke="${IC_STEEL}" stroke-width="5"/>${IC_L(kx,ky-kr-12,kx,ky-kr+12,'#343A40',4)}${IC_L(kx,ky,(kx+kr*Math.cos(pa)).toFixed(1),(ky-kr*Math.sin(pa)).toFixed(1),ORG,5)}<circle cx="${(kx+kr*Math.cos(pa)).toFixed(1)}" cy="${(ky-kr*Math.sin(pa)).toFixed(1)}" r="9" fill="${ORG}"/>
  ${IC_T(kx-30,ky-kr-4,'TDC',{fs:20,fw:800,a:'end'})}${IC_T(186,254,'peak pressure',{fs:22,fw:800,fill:ORG})}${IC_T(186,284,'≈ 15° after TDC',{fs:22,fill:IC_GREY})}</g>`};
 ICON.icAir=(x,y)=>{const dots=(x0,y0,n)=>{let q='';for(let i=0;i<n;i++){q+=`<circle cx="${x0+24+(i%4)*30}" cy="${y0+26+Math.floor(i/4)*30}" r="9" fill="${IC_WATER}"/>`}return q};return `<g transform="translate(${x-210} ${y-165})">
  ${IC_box(10,60,160,160,{st:IC_WATER,sw:3,r:10})}${dots(10,60,14)}${IC_T(90,44,'25 °C, 1.00 bar',{fs:22,fw:700,a:'middle',fill:IC_WATER})}${IC_T(90,256,'40.0 kW',{fs:26,fw:800,a:'middle',fill:IC_WATER})}
  ${IC_arrow(180,140,236,140,IC_GREY,4)}
  ${IC_box(250,60,160,160,{st:ORG,sw:3,r:10})}${dots(250,60,12)}${IC_T(330,44,'40 °C, 0.90 bar',{fs:22,fw:700,a:'middle',fill:ORG})}${IC_T(330,256,'34.27 kW',{fs:26,fw:800,a:'middle',fill:ORG})}</g>`};
}
